"""Native SAM review output is generated by the runtime, not inferred from objective mappings."""
import asyncio
from dataclasses import replace

import pytest
from pydantic import ValidationError
from conftest import ScriptedRunner, SYLLABUS
from phact_agents.pipeline import AnalysisRequest, analyze
from phact_agents.schemas import SamCompetencySynthesis, SamModernizationSynthesis, SynthesisOutput, SamCompetencyDetails
from phact_agents.service import handle


class ReviewRunner(ScriptedRunner):
    async def run(self, **kwargs):
        model = kwargs["output_model"]
        if model in (SamCompetencySynthesis, SamModernizationSynthesis):
            local = dict(kwargs, output_model=SynthesisOutput)
            base = (await super().run(**local)).model_dump()
            assert "<faculty_context>" in kwargs["prompt"]
            if model is SamCompetencySynthesis:
                assert "<authoritative_competencies>" in kwargs["prompt"]
                details = {"competencies": [{"code": f"D2-{n}", "status": "NOT_ADDRESSED", "evidence": "", "rationale": "No assessment"} for n in range(1, 23)], "changes": []}
            else:
                details = {"recommendations": [{"title": "Assessment", "category": "ASSESSMENT_TOOLS", "approach": "AI_RESISTANT", "target": "Final", "recommendation": "Add an oral defense", "rationale": "Check reasoning", "peerExampleIds": ["S1", "Z9"], "excerpts": ["Oral defence"]}]}
            return model.model_validate({**base, "sam_review": details})
        return await super().run(**kwargs)


@pytest.mark.parametrize("kind", ["COMPETENCY", "MODERNIZATION"])
def test_runtime_returns_native_review_and_skips_duplicate_storage(make_deps, settings, kind):
    settings = replace(settings, results_bucket="should-not-write", postprocess_function="should-not-invoke")
    payload = {"job_id": "r1", "syllabus_id": "s1", "owner_sub": "u1", "syllabus_text": SYLLABUS, "review_type": kind,
               "guidance": "Keep original weeks", "declined": ["Previous idea"],
               "competency_reference": [{"code": f"D2-{n}"} for n in range(1, 23)]}
    out = asyncio.run(handle(payload, settings, deps_factory=lambda s: make_deps(runner=ReviewRunner(delay=0), s=s)))
    assert out["status"] == "SUCCEEDED", out
    assert out["result_key"] is None and not out["postprocess_triggered"]
    result = out["result"]["samReview"]
    assert "revisedSyllabus" in result
    if kind == "COMPETENCY":
        assert len(result["competencies"]) == 22
    else:
        assert result["recommendations"][0]["peerExampleIds"] == ["S1"]


def test_incomplete_or_duplicate_grades_rejected():
    row = {"code": "D2-1", "status": "PARTIAL", "evidence": "", "rationale": "x"}
    for rows in [[row], [row] * 22]:
        with pytest.raises(ValidationError):
            SamCompetencyDetails(competencies=rows, changes=[])


def test_missing_authoritative_competencies_fails_before_model(make_deps):
    request = AnalysisRequest("r", "s", SYLLABUS, review_type="COMPETENCY")
    with pytest.raises(ValueError, match="authoritative"):
        asyncio.run(analyze(request, make_deps()))
